brand_css_dark:
:root {
--radius-none: 0;      /* 버튼(--btn-radius:0)·블록·패널 */
--radius-sm: 2px;      /* --radius .125rem — 이미지·카드 */
--radius-md: 4px;      /* (추정) 앱 칩·입력 */
--radius-lg: 8px;      /* (추정) 팝오버·모달 */
--radius-xl: 12px;     /* (추정) 앱 창 모서리 */
--radius-full: 9999px; /* 상태 점·웹 chip(20px) 전용 */
--shadow-none: none;                              /* 기본 — 웹 --shadow: none */
--shadow-sm: 0 0 0 1px var(--border-default);     /* 괘선형 구획(그림자 대신 선) */
--shadow-md: 0 4px 12px rgba(0,0,0,0.24);         /* (추정) 드롭다운·명령 팔레트 */
--shadow-lg: 0 8px 30px rgba(0,0,0,0.12);         /* 웹 --img-shadow 실측 — 제품 스크린샷 */
--shadow-xl: 0 24px 64px rgba(0,0,0,0.45);        /* (추정) 앱 창 전체 */
--duration-fast: 100ms;   /* 호버 색 전환 */
--duration-base: 200ms;   /* 드롭다운·탭 */
--duration-slow: 400ms;   /* 섹션 전환·스크롤 서브내비(.25s) */
--ease-out: cubic-bezier(0.4, 0, 0.2, 1);     /* --easing 실측 */
--ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);  /* 같은 곡선 재사용 */
}
:root {
  /* Primary - Warp 8-bit Blue (웹 브랜드 팔레트) */
  --color-primary-50:  #EEEDFF;  /* (추정) 선택 행 옅은 면 */
  --color-primary-100: #DCD9FF;  /* (추정) */
  --color-primary-200: #B9B3FF;  /* (추정) */
  --color-primary-300: #9189FF;  /* (추정) */
  --color-primary-400: #7267FF;  /* --accent-2 실측 — 다크 위 링크 */
  --color-primary-500: #2A1EFF;  /* --p-8bit 실측 — 브랜드 대표색, 번호·링크·서브내비 */
  --color-primary-600: #2016D6;  /* (추정) hover */
  --color-primary-700: #1910A8;  /* (추정) pressed */
  --color-primary-800: #120B7A;  /* (추정) */
  --color-primary-900: #0D0A3D;  /* --p-night 실측 */

  /* Secondary - 앱 테마 강조색 / 웹 보조 */
  --color-secondary-500: #3780E9;  /* Phenomenon blue — 버튼 hover·강조 테두리 */
  --color-accent-500:    #2E5D9E;  /* Phenomenon accent — 기본 버튼·커서 */
  --color-yield-500:     #EEF17C;  /* --p-yield 실측 — 웹 「book a demo」 노랑 */
  --color-lilac-500:     #B7A4F2;  /* --p-lilac 실측 */

  /* Neutral */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #FAF9F6;  /* Phenomenon foreground */
  --color-neutral-100:  #E6E6E6;  /* modal feature title */
  --color-neutral-300:  #9B9B9B;  /* modal feature description */
  --color-neutral-500:  #616161;  /* ANSI black (dark) */
  --color-neutral-700:  #2A2A2A;  /* modal background */
  --color-neutral-900:  #121212;  /* Phenomenon background */
  --color-neutral-1000: #050505;  /* Dark 테마 배경 */

  /* Semantic - Phenomenon ANSI */
  --color-success-bg: #1CA05A26;
  --color-success-fg: #1CA05A;   /* ANSI green */
  --color-warning-bg: #E5A01A26;
  --color-warning-fg: #E5A01A;   /* ANSI yellow */
  --color-error-bg:   #D22D1E26;
  --color-error-fg:   #D22D1E;   /* ANSI red */
  --color-info-bg:    #3780E926;
  --color-info-fg:    #3780E9;   /* ANSI blue */

  /* Surface */
  --bg-base:     #121212;  /* 터미널 캔버스 */
  --bg-subtle:   #1C1C1C;  /* (추정) 탭 사이드바·선택 블록 */
  --bg-elevated: #232323;  /* (추정) 칩·팝오버 */
  --bg-overlay:  #2A2A2A;  /* 모달 배경 실측 */

  /* Text (FAF9F6 알파를 #121212에 합성) */
  --text-primary:    #FAF9F6;  /* foreground */
  --text-secondary:  #E2E1DE;  /* body_text 90% */
  --text-tertiary:   #9D9C9A;  /* label_text 60% */
  --text-on-primary: #FAF9F6;  /* primary_button_text */
  --text-disabled:   #868584;  /* disabled_label 50% */

  /* Border */
  --border-default: #333333;  /* (추정) */
  --border-subtle:  #404040;  /* subtle_border 20% 합성 */
  --border-strong:  #5A5A5A;  /* (추정) */
  --border-focus:   #3780E9;  /* surface_border = blue */
}

[data-theme="light"] {
  /* 번들 「Light」 테마 + 웹 라이트 팔레트 */
  --color-secondary-500: #00C2FF;  /* Light 테마 accent */
  --color-accent-500:    #2A1EFF;
  --color-success-fg: #10A778;  /* Light ANSI green */
  --color-warning-fg: #A89C14;  /* Light ANSI yellow */
  --color-error-fg:   #C30771;  /* Light ANSI red */
  --color-info-fg:    #008EC4;  /* Light ANSI blue */
  --color-success-bg: #10A7781F;
  --color-warning-bg: #A89C141F;
  --color-error-bg:   #C307711F;
  --color-info-bg:    #008EC41F;

  --bg-base:     #FFFFFF;  /* Light 배경 */
  --bg-subtle:   #F6F5FB;  /* --p-cool-white 웹 패널 */
  --bg-elevated: #FFFFFF;
  --bg-overlay:  #FFFFFF;

  --text-primary:    #111111;  /* Light foreground (17,17,17) */
  --text-secondary:  #5D5966;  /* 웹 --muted */
  --text-tertiary:   #918D9A;  /* 웹 --muted-2 */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #B3B0BA;  /* (추정) */

  --border-default: #0D0A3D29;  /* 웹 --line */
  --border-subtle:  #0D0A3D12;  /* 웹 --line-soft */
  --border-strong:  #1A1522;    /* 웹 --p-space */
  --border-focus:   #2A1EFF;
}




.wp-btn { display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px; border: 1px solid var(--border-default); border-radius: 0; font: 600 12px/1 'Matter Mono', Hack, ui-monospace, monospace; text-transform: lowercase; cursor: pointer; transition: background var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out); }
.wp-btn--primary { background: var(--text-primary); color: var(--bg-base); border-color: var(--text-primary); }
.wp-btn--primary:hover { background: var(--color-primary-500); border-color: var(--color-primary-500); color: #fff; }
.wp-btn--primary:active { background: var(--color-primary-700); border-color: var(--color-primary-700); }
.wp-btn--secondary { background: var(--color-yield-500); color: #1A1522; border-color: var(--color-yield-500); }  /* book a demo */
.wp-btn--secondary:hover { filter: brightness(0.95); }
.wp-btn--ghost { background: var(--bg-base); color: var(--text-primary); }
.wp-btn--ghost:hover { border-color: var(--color-primary-500); color: var(--color-primary-500); }
.wp-btn--danger { background: var(--color-error-fg); color: #fff; border-color: var(--color-error-fg); }
.wp-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.wp-btn.is-loading { pointer-events: none; }
.wp-btn.is-loading::after { content: "▍"; animation: wp-blink 1s steps(1) infinite; }  /* 커서 깜빡임 */
@keyframes wp-blink { 50% { opacity: 0; } }
.wp-input { width: 100%; height: 40px; padding: 0 12px; border: 0; border-radius: var(--radius-md); background: var(--bg-subtle); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-default); font: 400 13px/1.4 Hack, 'D2Coding', ui-monospace, monospace; caret-color: var(--color-secondary-500); }
.wp-input::placeholder { color: var(--text-tertiary); }
.wp-input:focus { outline: none; box-shadow: inset 0 0 0 1px var(--border-focus); }
.wp-input.is-error { box-shadow: inset 0 0 0 1px var(--color-error-fg); }
.wp-input:disabled { color: var(--text-disabled); background: var(--bg-base); }
.wp-block { padding: 10px 16px; background: var(--bg-base); box-shadow: inset 0 -1px 0 var(--border-default); font: 400 13px/1.5 Hack, ui-monospace, monospace; }
.wp-block__meta { font-size: 11px; color: var(--text-tertiary); }
.wp-block--selected { background: var(--bg-subtle); box-shadow: inset 2px 0 0 var(--color-secondary-500), inset 0 -1px 0 var(--border-default); }
.wp-block--error { box-shadow: inset 2px 0 0 var(--color-error-fg), inset 0 -1px 0 var(--border-default); }
.wp-panel { border: 1px solid var(--border-default); border-radius: 0; background: var(--bg-base); }
.wp-panel__bar { display: flex; align-items: center; gap: 14px; padding: 8px 12px; border-bottom: 1px solid var(--border-default); font: 400 10.5px/1 'Matter Mono', Hack, monospace; letter-spacing: 0.1em; color: var(--text-tertiary); }
.wp-badge { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 6px; border-radius: var(--radius-md); font: 400 11px/1 Hack, ui-monospace, monospace; }
.wp-badge--solid { background: var(--color-primary-500); color: #fff; }
.wp-badge--subtle { background: var(--bg-elevated); color: var(--text-secondary); }
.wp-badge--outline { box-shadow: inset 0 0 0 1px var(--border-default); color: var(--text-secondary); }  /* 경로·브랜치 칩 */
.wp-tag { font: 400 11px/1 'Matter Mono', monospace; color: var(--color-primary-500); text-transform: lowercase; }
.wp-tag::before { content: "# "; }
.wp-tabs { width: 200px; background: var(--bg-subtle); box-shadow: inset -1px 0 0 var(--border-default); padding: 8px; display: flex; flex-direction: column; gap: 4px; font: 400 12px/1.4 Roboto, -apple-system, sans-serif; }
.wp-tab { padding: 6px 8px; border-radius: var(--radius-md); color: var(--text-tertiary); }
.wp-tab:hover { background: var(--bg-elevated); color: var(--text-secondary); }
.wp-tab.is-active { background: var(--bg-base); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-default); }
